import React from "react";
import "./style.css";
import BtnDarkMode from "../btnDarkMode/BtnDarkMode";
import { Link } from "react-router-dom";

const Header = () => {
  const openWindow = (page) => {
    window.open(`/${page}.html`, "_blank", "width=1400,height=760");
  };

  return (
    <header className="header"
    style={{
      width: '100%',
      backgroundColor: '#111'
    }}>
      <div className="logo"
      style={{
        color: 'blue'
      }}>Freelance portfolio</div>

            <nav style={{ padding: '25px', background: '#000', borderBottom: '1px solid #222', textAlign: 'center' }}>
              <Link to="/projects" style={linkStyle}>Projects</Link>
              <Link to="/skills" style={linkStyle}>Skills</Link>
              <Link to="/contacts" style={linkStyle}>Contacts</Link>
            </nav>
        <BtnDarkMode />

    </header>
  );
};

export default Header;
